			unlock = {
				{ type = "quest", id = 68 },
				{ type = "quest", id = 70 },
			},
			text = [=[The town registry kept two addresses for Stalvan. At {link:moonbrook}Moonbrook{/link}, a letter he never sent told of his joy at building a school. At the Lion's Pride Inn in {link:goldshire}Goldshire{/link}, another waited, left behind by a messenger who fled one stormy night. In it Stalvan offered his services as a tutor to a noble house.]=],
