			unlock = {
				{ type = "quest", id = 225 },
				{ type = "quest", id = 227 },
			},
			text = [=[He was buried quickly, without rites, beyond the cemetery's edge. Days later the earth had been disturbed, and the grave was empty. The historian of {link:darkshire}Darkshire{/link}, who had known {link:morgan-stern}Morgan{/link} before the war, keeps a book that tells his story.]=],
		},
		{
			key = "a-daughter-s-ring",
			title = "A Daughter's Ring",
			hint = "Bring comfort to the grave of Morgan Ladimore.",
			unlock = {
				{ type = "quest", id = 231 },
			},
			text = [=[{link:morgan-stern}Morgan{/link} died believing his whole family dead. One daughter, Sarah, had lived. When her ring was laid on his grave, a voice rose on the wind. The knight spoke his daughter's name in wonder, and the weight on his soul was lifted. He gave his sword Archeus to the one who had brought him peace, and his last words were for his wife, Lys.]=],
