Add({
	kind = "topic",
	id = "the-night-watch",
	title = "The Night Watch",
	aliases = { "Night Watch", "Watchers" },
	category = "group",
	region = "duskwood",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Night Watch is the militia of {link:darkshire}Darkshire{/link}. It was raised when a foul magic seeped into {link:duskwood}Duskwood{/link} and {link:stormwind-city}Stormwind{/link} called its guards home. Since then the Watch has been all that stands between the town and the forest. It is led by {link:commander-althea-ebonlocke}Commander Althea Ebonlocke{/link}, and its members are called Watchers.]=],
		},
		{
			title = "The Watchers",
			text = [=[Watchers guard the gates and the square of {link:darkshire}Darkshire{/link}, and a few hold lonely posts on the roads: two on the western road, one on the northern road beside a goblin trader. They are too few, and they know it. Their commander cannot send them far from town. When the dead rise in the cemeteries, she must ask strangers to go in their place. The dead knight {link:mor-ladim}Mor'Ladim{/link} has killed some of her strongest.]=],
		},
		{
			title = "The Watch and the World",
			text = [=[{link:darkshire}Darkshire{/link} has come to rely on the Watch as its only army. When {link:magistrate-solomon}Magistrate Solomon{/link} of {link:lakeshire}Lakeshire{/link} begged {link:lord-ello-ebonlocke}Lord Ebonlocke{/link} for it, the mayor refused: if the Watch marched, the town would fall before it reached the edge of the forest. Not everyone admires it. The hunter {link:calor}Calor{/link} left the Watch for {link:carevin-family}the Carevin family{/link}, calling it complacent. Among the Watchers are {link:sarah-ladimore}Sarah Ladimore{/link}, daughter of a fallen knight, and, in the tales of {link:raven-hill}Raven Hill{/link}, the archer Merrick Valor.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "nightbane-worgen",
	title = "Nightbane Worgen",
	aliases = { "Nightbane", "Nightbane worgen" },
	category = "creature",
	region = "duskwood",
	unlock = {
		{ type = "target" },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Nightbane are the {red:worgen}worgen{/red} of {link:duskwood}Duskwood{/link}: great wolf-men who hunt the southern half of the forest in packs. Shadow weavers and dark runners roam {link:brightwood-grove}Brightwood Grove{/link} and the Rotting Orchard. The strongest of them, the vile fangs and the tainted ones, keep their bonfires near the caves of the south and in the mine of {link:roland-s-doom}Roland's Doom{/link}.]=],
		},
		{
			title = "Their Coming",
			text = [=[The worgen were not always here. The hunters of {link:darkshire}Darkshire{/link} say they appeared as if out of thin air, and the first were found in {link:roland-s-doom}Roland's Doom{/link}. A miner of that mine, the man called {link:jitters}Jitters{/link}, tells how it happened. He found the haft of a scythe in a pile of rubble and pulled it free. That night the worgen came out of every hole and ledge in the tunnels, and most of the miners died. He lost the scythe in his flight. He does not know whether it was he who brought the wolf-men to {link:duskwood}Duskwood{/link}, but he fears it.

The scythe was the {red:scythe-of-elune}Scythe of Elune{/red}. A {link:night-elves}night elf{/link} priestess, Velinde Starsong, had carried it into these woods, and her fate was learned in the mines. The {link:sentinels}Sentinels{/link} of {link:darnassus}Darnassus{/link} were troubled that a gift of their goddess had left her servants' hands.]=],
		},
		{
			title = "The War Against Them",
			text = [=[The Carevin family and their hunter {link:calor}Calor{/link} wage an endless war on the Nightbane. Every pack they destroy is soon replaced. No one in {link:darkshire}Darkshire{/link} yet knows what power draws them.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle of these days explains how the Scythe called the worgen, or whether the Nightbane are kin to the worgen of {link:silverpine-forest}Silverpine Forest{/link}.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "the-valor-family",
	title = "The Valor Family",
	aliases = { "Valor family" },
	category = "group",
	region = "duskwood",
	unlock = {
		{ type = "quest", id = 96139 },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Valor family were the defenders of {link:raven-hill}Raven Hill{/link} before it fell. A tome found in the ruined village, {i}Memories of Valor{/i}, records them one by one. Its writer grieves for them and blames himself for their absence.]=],
		},
		{
			title = "The Family",
			text = [=[• {b}Lord Grant Valor.{/b} The head of the family and the leader of {link:raven-hill}Raven Hill{/link}. When darkness came into the woods, he was the first to rally the villagers. He hated the undead above all foes and patrolled the cemeteries himself. A grave wound from them never truly healed.
• {b}Lady Cassandra Valor.{/b} His wife. Little is known of her but her love for her family.
• {b}Silvia Valor.{/b} A guard of Raven Hill, famed for putting bandits and swindlers to the sword. It is said she never abandoned the farms of {link:duskwood}Duskwood{/link}.
• {b}Ira Valor.{/b} When her father fell ill, she went into the forest to gather food, and she came to prefer the dark woods to the village. Lost travellers speak of a shadow that leads them back to the road.
• {b}Merrick Valor.{/b} The youngest son. He joined the {link:the-night-watch}Night Watch{/link} and kept the roads with his bow.]=],
		},
		{
			title = "Their Ghosts",
			text = [=[The Valors vanished all at once. Now their spirits walk the forest, still at the work they did in life: Grant among the skeletons of the cemetery, Silvia near the farmsteads, Ira in the woods, Merrick on the roads. {link:sirra-von-indi}Sirra Von'Indi{/link}, the historian of {link:darkshire}Darkshire{/link}, believes some shared grief binds them to this world.]=],
		},
		{
			title = "Unrecorded",
			text = [=[What befell the Valors, and what holds their spirits, is not yet known.]=],
		},
	},
})

